import sys

def main():
    data = sys.stdin.read().strip().split()
    if not data:
        return
    N = float(data[0])
    K = int(data[1])

    if K == 0:
        result = N
    else:
        result = N // (2 ** K) if N % (2 ** K) == 0 else N / (2 ** K)

    result = round(result, 2)

    if result == int(result):
        print(int(result))
    else:
        print("{:.2f}".format(result))

if __name__ == "__main__":
    main()
